<?php
declare(strict_types=1);require __DIR__.'/config.php';$actor=require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$action=(string)($_POST['action']??'');
 if($action==='create_admin'){
  require_owner();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');$role=(string)($_POST['role']??'admin');
  if($name===''||mb_strlen($name)>100||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12||!in_array($role,['admin','moderator'],true)){$notice='Invalid fields. Use a valid email and password of at least 12 characters.';}
  else{try{$q=$pdo->prepare('INSERT INTO admin_users(name,email,password_hash,role,is_active) VALUES(?,?,?,?,1)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role]);audit($pdo,'admin.created','admin',(string)$pdo->lastInsertId(),['role'=>$role]);$notice='Admin account created.';}catch(Throwable $e){$notice='Could not create account; email may already be in use.';}}
 }elseif($action==='toggle_admin'){
  require_owner();$id=filter_var($_POST['admin_id']??null,FILTER_VALIDATE_INT);
  if(!$id||(int)$id===$actor['id'])$notice='Invalid target.';
  else{$q=$pdo->prepare("UPDATE admin_users SET is_active=IF(is_active=1,0,1) WHERE id=? AND role IN ('admin','moderator')");$q->execute([$id]);audit($pdo,'admin.toggled','admin',(string)$id);$notice=$q->rowCount()?'Admin status updated.':'No change made.';}
 }else{http_response_code(400);exit('Invalid action.');}
}
$counts=[];foreach(['users'=>'users','conversations'=>'conversations','messages'=>'messages'] as $label=>$table){try{$counts[$label]=(int)$pdo->query("SELECT COUNT(*) FROM $table")->fetchColumn();}catch(Throwable $e){$counts[$label]=null;}}
$admins=$pdo->query('SELECT id,name,email,role,is_active,last_login_at FROM admin_users ORDER BY created_at DESC LIMIT 100')->fetchAll();
$logs=$pdo->query('SELECT l.action,l.target_type,l.target_id,l.created_at,a.name AS admin_name FROM admin_audit_logs l LEFT JOIN admin_users a ON a.id=l.admin_id ORDER BY l.id DESC LIMIT 30')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Talviro Admin</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#eef2ff;font:15px system-ui}header{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;padding:18px 4%;background:#121a2e;border-bottom:1px solid #29324c}main{max-width:1100px;margin:24px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.card{background:#121a2e;border:1px solid #29324c;border-radius:15px;padding:18px;margin-bottom:16px}.num{font-size:28px;font-weight:800}input,select{padding:10px;border-radius:8px;border:1px solid #3a4563;background:#0b1020;color:white;max-width:100%}button,.btn{padding:10px 14px;border:0;border-radius:8px;background:#6c7cff;color:white;font-weight:700;cursor:pointer;text-decoration:none}table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}td,th{text-align:left;padding:10px;border-bottom:1px solid #29324c;white-space:nowrap}.muted{color:#aab4d0}.notice{padding:12px;background:#202d4a;border-radius:9px}.formrow{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}</style></head><body><header><strong>Talviro Chat · Admin Console</strong><span><?=e($actor['name'])?> (<?=e($actor['role'])?>) <a class="btn" href="logout.php">Sign out</a></span></header><main>
<?php if($notice!==''):?><p class="notice"><?=e($notice)?></p><?php endif;?>
<div class="grid"><?php foreach(['users'=>'Registered users','conversations'=>'Conversations','messages'=>'Messages'] as $k=>$label):?><section class="card"><div class="muted"><?=e($label)?></div><div class="num"><?=$counts[$k]===null?'—':$counts[$k]?></div></section><?php endforeach;?><section class="card"><div class="muted">Your role</div><div class="num"><?=e(strtoupper($actor['role']))?></div></section></div>
<section class="card"><h2>Admin controls</h2><p class="muted">This first version manages admin access and shows counts/audit events. User bans, reports, message moderation, global feature settings and broadcast notifications must be connected to their API workflows before use.</p></section>
<?php if($actor['role']==='owner'):?><section class="card"><h2>Create admin / moderator</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_admin"><div class="formrow"><input name="name" placeholder="Full name" maxlength="100" required><input name="email" type="email" placeholder="Email" maxlength="190" required><input name="password" type="password" placeholder="Password (12+ chars)" minlength="12" required><select name="role"><option value="admin">Admin</option><option value="moderator">Moderator</option></select><button>Create</button></div></form></section><?php endif;?>
<section class="card"><h2>Admin accounts</h2><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Last login</th><?php if($actor['role']==='owner'):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($admins as $a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['email'])?></td><td><?=e($a['role'])?></td><td><?=$a['is_active']?'Active':'Disabled'?></td><td><?=e($a['last_login_at']??'Never')?></td><?php if($actor['role']==='owner'):?><td><?php if($a['role']!=='owner'&&(int)$a['id']!==$actor['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_admin"><input type="hidden" name="admin_id" value="<?=(int)$a['id']?>"><button><?=$a['is_active']?'Disable':'Enable'?></button></form><?php else:?>—<?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></section>
<section class="card"><h2>Recent audit events</h2><table><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Target</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['admin_name']??'System')?></td><td><?=e($l['action'])?></td><td><?=e(($l['target_type']??'').':'.($l['target_id']??''))?></td></tr><?php endforeach;?></tbody></table></section>
</main></body></html>
